using System.Net;
using System.Text;
using System.Text.Json;
using Arcoll.WinUI3.Services;
int checks=0;void Check(bool ok,string name){checks++;if(!ok)throw new Exception(name);}
var catalogPath=Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"../../../../../assets/themes/catalog.json"));
if(!File.Exists(catalogPath))catalogPath=Path.Combine(Directory.GetCurrentDirectory(),"assets/themes/catalog.json");
using var catalog=JsonDocument.Parse(File.ReadAllText(catalogPath));
foreach(var item in catalog.RootElement.GetProperty("themes").EnumerateObject())foreach(var mode in new[]{"theme","light","dark","auto"})foreach(var windowsLight in new[]{true,false}){var visual=JsonSerializer.Deserialize<Dictionary<string,object?>>(item.Value.GetRawText())!;visual["mode"]=mode;var element=JsonSerializer.SerializeToElement(visual);var palette=ThemeRules.Resolve(element,windowsLight);Check(palette is not null,"theme resolves "+item.Name+"/"+mode);Check(palette!.Id==item.Name,"identity preserved");Check(ThemeRules.IsLight(palette.Surface)==(mode=="light"||mode=="auto"&&windowsLight||mode=="theme"&&item.Value.GetProperty("light").GetBoolean()),"correct mode");}
Check(ThemeRules.Resolve(JsonSerializer.SerializeToElement(new{id="<script>",mode="theme"}),true)is null,"invalid ID refused");Check(!ThemeRules.IsHex("url(https://example.test)"),"only solid colors");
var secret=new string('a',64);var cleaned=DiagnosticRedactor.Clean("download_key='"+secret+"' password=\"my multi word password\" ?t="+secret+" Bearer abc.def");Check(!cleaned.Contains(secret)&&!cleaned.Contains("multi word")&&!cleaned.Contains("abc.def"),"secrets redacted before spooling");Check(DiagnosticRedactor.Clean(new string('界',16000)).Length<3900,"line bounded");
var temp=Path.Combine(Path.GetTempPath(),"ti-log-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);try{var logs=Path.Combine(temp,"source","logs");Directory.CreateDirectory(logs);var file=Path.Combine(logs,"runtime.log");File.WriteAllText(file,"one\r\nsecond 界\n",new UTF8Encoding(false));var chunk=DiagnosticLogReader.Read(file,0,"runtime");Check(chunk.Events.Length==2,"UTF8 lines");Check(chunk.EndOffset==new FileInfo(file).Length,"byte cursor correct");Check(DiagnosticLogReader.Read(file,chunk.EndOffset,"runtime").Events.Length==0,"no replay on unchanged file");File.AppendAllText(file,"three\n",new UTF8Encoding(false));Check(DiagnosticLogReader.Read(file,chunk.EndOffset,"runtime").Events.Single().Message=="three","only appended line");var unicode=Path.Combine(logs,"windows.txt");File.WriteAllText(unicode,"primeiro\r\nsegundo\r\n",Encoding.Unicode);Check(DiagnosticLogReader.Read(unicode,0,"windows").Events.Length==2,"UTF16 Windows logs");
 var handler=new FakeHandler();LogIdentity identity=new("https://fixture.test",new string('b',64),"TEST1",secret);var state=Path.Combine(temp,"state");using var uploader=new CentralLogUploader(()=>identity,state,[(Path.Combine(temp,"source"),"test")],handler);await uploader.PumpOnceAsync(default);Check(Directory.GetFiles(Path.Combine(state,"outbox"),"*.json",SearchOption.AllDirectories).Length>0,"durable outbox before network");Check(handler.Calls==0,"spooling does not claim success");await uploader.PumpOnceAsync(default);Check(handler.Calls>0,"HTTPS transport attempted");Check(Directory.GetFiles(Path.Combine(state,"outbox"),"*.json",SearchOption.AllDirectories).Length==0,"delete only after matching ACK");
 File.AppendAllText(file,"pending A\n");await uploader.PumpOnceAsync(default);handler.Reject=true;await uploader.PumpOnceAsync(default);Check(Directory.GetFiles(Path.Combine(state,"outbox"),"*.json",SearchOption.AllDirectories).Length>0,"offline preserves queue");handler.Reject=false;identity=identity with{SiteCode="TEST2"};var before=handler.Calls;await uploader.PumpOnceAsync(default);Check(handler.Calls==before,"another network cannot flush old queue");File.AppendAllText(file,"new B\n");await uploader.PumpOnceAsync(default);await uploader.PumpOnceAsync(default);Check(handler.LastMessages.SequenceEqual(new[]{"new B"}),"network transfer seeds source cursors instead of replaying old client data");
}finally{Directory.Delete(temp,true);}Console.WriteLine($"PASS {checks} catalog, redaction, byte cursors and durable log transport assertions.");
sealed class FakeHandler:HttpMessageHandler{public int Calls;public bool Reject;public string[] LastMessages=[];protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){Calls++;using var payload=JsonDocument.Parse(await request.Content!.ReadAsStringAsync(ct));var root=payload.RootElement;LastMessages=root.GetProperty("events").EnumerateArray().Select(e=>e.GetProperty("message").GetString()!).ToArray();if(Reject)return new(HttpStatusCode.ServiceUnavailable){Content=new StringContent("{}")};var id=root.GetProperty("batch_id").GetString();return new(HttpStatusCode.OK){Content=new StringContent(JsonSerializer.Serialize(new{ok=true,batch_id=id,accepted=root.GetProperty("events").GetArrayLength()}))};}}
